async (page) => {
  const events = [];
  let cur = null;
  page.on('pageerror', e => events.push({sec: cur, type: 'pageerror', msg: e.message}));
  page.on('console', m => { if (m.type()==='error') events.push({sec: cur, type:'console', msg: m.text()}); });
  const buttons = await page.getByRole('button').all();
  const labels = [];
  for (const b of buttons) labels.push(await b.evaluate(el => (el.closest('section,div')?.innerText||'').slice(0,80) + ' | ' + el.textContent));
  for (let i=0;i<buttons.length;i++) { cur = i; await buttons[i].click(); await page.waitForTimeout(1500); }
  await page.waitForTimeout(2000);
  return {labels, events};
}

